// Iterator protocol by hand, and what for...of does
class Countdown {
  constructor(n) { this.n = n; }
  [Symbol.iterator]() { // makes it iterable
    let n = this.n;
    return {
      next() { return n > 0 ? { value: n--, done: false } : { value: undefined, done: true }; },
      return() { console.log('  return() called: cleanup'); return { done: true }; }, // runs on early exit
    };
  }
}
