// Fix 3: bounded LRU cache for primitive keys such as URLs
class LRU {
  constructor(max) { this.max = max; this.m = new Map(); }
  get(k) {
    if (!this.m.has(k)) return undefined;
    const v = this.m.get(k);
    this.m.delete(k); this.m.set(k, v); // move to newest
    return v;
  }
  set(k, v) {
    this.m.delete(k); this.m.set(k, v);
    if (this.m.size > this.max) this.m.delete(this.m.keys().next().value); // evict oldest
  }
}
