// Mini Vue-style reactivity with Proxy
let activeEffect = null;
const targetMap = new WeakMap(); // target -> Map(key -> Set(effects))

function track(target, key) {
  if (!activeEffect) return;
  let deps = targetMap.get(target);
  if (!deps) targetMap.set(target, (deps = new Map()));
  let set = deps.get(key);
  if (!set) deps.set(key, (set = new Set()));
  set.add(activeEffect);
  activeEffect.deps.push(set);
}
function trigger(target, key) {
  const set = targetMap.get(target)?.get(key);
  if (set) [...set].forEach(run => run()); // copy to avoid endless loops while mutating
}
function reactive(obj) {
  return new Proxy(obj, {
    get(t, k, r) { track(t, k); return Reflect.get(t, k, r); },
    set(t, k, v, r) {
      const old = t[k];
      const ok = Reflect.set(t, k, v, r);
      if (!Object.is(old, v)) trigger(t, k); // only when value really changed
      return ok;
    },
  });
}
function effect(fn) {
  const run = () => {
    run.deps.forEach(s => s.delete(run)); // forget old deps (conditional branches)
    run.deps = [];
    activeEffect = run;
    try { fn(); } finally { activeEffect = null; }
  };
  run.deps = [];
  run();
}
